'use strict';
// UI currency symbols only (records keep their ISO code). The riyal (U+E900) and dirham (U+E901) signs come from assets/currency_symbols.ttf.
const uiCurrencySymbols={USD:'$',EUR:'€',GBP:'£',INR:'₹',PKR:'Rs ',SAR:'\uE900 ',AED:'\uE901 '};
function uiMoney(currency,amount){return `${uiCurrencySymbols[currency]??`${String(currency).replace(/[&<>"']/g,'')} `}${amount}`;}
// Currency picker: the seven common currencies first, then the rest by code. 2-decimal currencies only (amounts show two decimals).
const uiCurrencyOptions=[['USD','US dollar'],['EUR','Euro'],['GBP','British pound'],['PKR','Pakistani rupee'],['AED','UAE dirham'],['INR','Indian rupee'],['SAR','Saudi riyal'],['AUD','Australian dollar'],['BDT','Bangladeshi taka'],['BRL','Brazilian real'],['CAD','Canadian dollar'],['CHF','Swiss franc'],['CNY','Chinese yuan'],['DKK','Danish krone'],['EGP','Egyptian pound'],['HKD','Hong Kong dollar'],['IDR','Indonesian rupiah'],['KES','Kenyan shilling'],['LKR','Sri Lankan rupee'],['MXN','Mexican peso'],['MYR','Malaysian ringgit'],['NGN','Nigerian naira'],['NOK','Norwegian krone'],['NPR','Nepalese rupee'],['NZD','New Zealand dollar'],['PHP','Philippine peso'],['PLN','Polish złoty'],['QAR','Qatari riyal'],['SEK','Swedish krona'],['SGD','Singapore dollar'],['THB','Thai baht'],['TRY','Turkish lira'],['ZAR','South African rand']].map(([value,detail])=>({value,label:value,detail}));
